(* [comment removed for export] *)
Definition P_AOS_RET1 : Z := 0x2f84c.
Definition ALLOC_OBJ_SCHED_STACK : Z := 48 + ALLOCATE_STACK.

Lemma ConfigSvc_cons_LB : forall LB b m c S, ConfigSvc LB m c S -> ConfigSvc (b :: LB) m c S.
Proof. intros LB b m c S (p & j4 & j7 & IN & R). exists p, j4, j7. split; [right; exact IN| exact R]. Qed.

Lemma sc_inv_cons_LB : forall LB b m ioc regb cfgb tp errv,
  sc_inv LB m ioc regb cfgb tp errv -> sc_inv (b :: LB) m ioc regb cfgb tp errv.
Proof.
  intros LB b m ioc regb cfgb tp errv (A & B & C & D). split; [exact A|]. split; [apply Registry_cons_LB; exact B|].
  split; [apply ConfigSvc_cons_LB; exact C| exact D].
Qed.

(* [comment removed for export] *)
Lemma sc_inv_xpres : forall LB SP m m' ioc regb cfgb tp errv errv',
  sc_inv LB m ioc regb cfgb tp errv -> xpres LB SP [] m m' -> SP <= ioc + 8 ->
  rw_cells usegs m' (bv_unsigned tp + -164) [C4 errv'] -> CanaryReads m' ->
  sc_inv LB m' ioc regb cfgb tp errv'.
Proof.
  intros LB SP m m' ioc regb cfgb tp errv errv' (RI & REG & CS & XS & CAN & ERR) XP LE ERR' CAN'. unfold O_IOC_REGISTRY in *.
  unfold sc_inv, O_IOC_REGISTRY.
  split. { eapply ro_cells_xpres; [exact XP| exact RI|]. split; [left; cbn; lia| constructor]. }
  split. { eapply Registry_xpres; [exact REG| exact XP| constructor]. }
  split. { destruct CS as (p & j4 & j7 & IN & C & E). exists p, j4, j7. split; [exact IN|]. split; [| exact E].
           eapply xpres_rw_cells; [exact XP| exact C|]. split; [| constructor].
