(* [comment removed for export] *)
Definition aos_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (S ioc regb cfgb lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 S) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (sc_W lo sp tp S regb) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ SchedCells m' S ioc
    /\ sc_inv LB m' ioc regb cfgb tp (wz 0).

Lemma aos_segB : forall (S ioc regb cfgb ownp allocb lo : Z) (LB : list block)
    sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (ra s0 s1 s2 : word)
    (F : bvmap 5 word) fc (m : mem) (errv : word) (j0 junkB : list byte),
  F = bvmap_empty -> fc = Z_to_bv 32 0 ->
  rw_cells usegs m (bv_unsigned sp + -48) [CB 8 j0; C8 (Z_to_bv 64 allocb); C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells usegs m S [CB 272 junkB] ->
  ro_cells usegs m ownp [CB 1 [b8 0]] -> bv_unsigned sp <= ownp -> ownp + 1 <= 2^64 ->
  sc_pure S ioc regb cfgb lo (Z_to_bv 64 (bv_unsigned sp + -48)) tp (Z_to_bv 64 0x2f880) ->
  sc_inv LB m ioc regb cfgb tp errv ->
  stk usegs m lo (bv_unsigned sp + -48) -> hceil + 48 <= bv_unsigned sp -> bv_unsigned ra mod 2 = 0 ->
  0 <= allocb < 2^64 ->
  mem_inv usegs m ->
  evt usegs (aos_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB S ioc regb cfgb lo m)
    (MS (mkR (Z_to_bv 64 P_AOS_RET1) (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2
             s0 (Z_to_bv 64 ioc) (Z_to_bv 64 S) a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 ownp) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
