Definition SchedRest (m : mem) (S : Z) : Prop :=
  exists j50 jm j109 je jt j219,
     rw_cells usegs m (S + O_SCH_ONE_THREAD) [CB 2 [b8 0; b8 0]; CB 6 j50]
  /\ rw_cells usegs m (S + O_SCH_MUTEX) [CB 8 jm]
  /\ PMutex m (S + O_SCH_PMUTEX) 0
  /\ rw_cells usegs m (S + O_SCH_SPIN) [C4 (wz 0); CB 1 [b8 1]; CB 3 j109]
  /\ rw_cells usegs m (S + O_SCH_EVENT) [CB 8 je]
  /\ PCond m (S + O_SCH_COND) CLOCK_MONOTONIC
  /\ rw_cells usegs m (S + O_SCH_EVSTATE)
       [C8 (wz 0); C8 (wz 0); C8 (wz P_SCHED_GET_DEFAULT_TASK); C8 (wz 0); C8 (wz 0); C4 (wz 0); CB 4 jt;
        CB 3 [b8 1; b8 0; b8 0]; CB 5 j219; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max); C8 (wz 0)].

Lemma SchedCells_split : forall m S ioc, SchedCells m S ioc -> rw_cells usegs m S (SvcHdrCells (sched_hdr0 ioc)) /\ SchedRest m S.
Proof.
  intros m S ioc (j50 & jm & j109 & je & jt & j219 & HDR & R). split; [exact HDR|]. exists j50, jm, j109, je, jt, j219. exact R.
Qed.

