(* [comment removed for export] *)
Definition mss_segA_post (sp gp tp t0 t1 t2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (r ownp ioc allocb lo : Z) (ra s0 s1 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m' j16,
    ms' = MS (mkR (Z_to_bv 64 P_MSS_RET1) (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2
                  (Z_to_bv 64 r) s1 (Z_to_bv 64 (bv_unsigned sp + -48)) (Z_to_bv 64 ioc) (Z_to_bv 64 ownp) a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_ALLOC_OBJ_SCHED) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -48)
    /\ rw_cells usegs m' (bv_unsigned sp + -48)
         [C8 (Z_to_bv 64 allocb); C8 (Z_to_bv 64 (P_MAKE_SVC_SCHED + 48)); CB 8 j16; C8 s1; C8 s0; C8 ra].

Lemma mss_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (r ownp ioc allocb lo : Z),
  ro_cells usegs m (r + O_REG_OWNER) [C8 (wz ioc)] -> ro_cells usegs m ioc [C8 (wz allocb)] ->
  stk usegs m lo (bv_unsigned sp) -> lo + 48 <= bv_unsigned sp -> hceil <= lo ->
  r + NEWSZ_REG <= lo -> bv_unsigned sp <= ioc -> ioc + 24 <= 2^64 -> 0 <= ownp < 2^64 ->
  ioc mod 8 = 0 ->                                                                            (* [comment removed for export] *)
  mem_inv usegs m ->
  evt usegs (mss_segA_post sp gp tp t0 t1 t2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc r ownp ioc allocb lo ra s0 s1 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 r) (Z_to_bv 64 ownp) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
